"""Deployment-readiness decision from the completed predeclared comparison."""
import sys,json
from pathlib import Path
import pandas as pd
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R))
from scripts.component_confirmation_v2 import P,ID,ARMS,SETTINGS
from model_lab.common import atomic_json,sha,verify_files
def read(p):return json.loads(p.read_text())
def main():
    verify_files(R,read(P/'proposal.json')['input_hashes']);v=read(P/'manager_verification.json');assert v['passed'];scores=pd.read_csv(P/'scores.csv');passed=v['confirmation_gate_passed'];labels={'adaptive_chips':'Samme adaptive manager med chips','no_chips':'Samme manager uten chips'};names={'component':'Komponentmodellen','operational_fixed':'Dagens operative modell'}
    lines=['# Komponentmodellen: ny test og hva som gjenstår før bruk','',
      '**Ny historisk kontroll: '+('BESTÅTT.' if passed else 'IKKE BESTÅTT.')+'** Begge modellene er testet på hele 2025/26, med samme daterte spillerutvalg, priser, åpningsbudsjett og manager. Det separate forsøket uten chips bruker samme begrensning for begge.','',
      '| Test | Komponentmodell | Dagens modell | Forskjell, netto poeng | Status |','|---|---:|---:|---:|---|']
    for a in v['paired_results']:
        z=scores[scores.setting.eq(a['setting'])].set_index('arm');values=['—' if pd.isna(z.loc[arm,'net']) else f'{z.loc[arm,"net"]:.0f}' for arm in ARMS];delta='—' if a['delta'] is None else f'{a["delta"]:+.0f}';status='Bestått' if a['passed'] else 'Ufullført' if not a['complete'] else 'Ikke bestått';lines.append(f'| {labels[a["setting"]]} | {values[0]} | {values[1]} | {delta} | {status} |')
    lines+=['','Kravene ble låst før denne testens sesongresultater: begge modellene må fullføre begge oppsett, alle kontroller må bestås, og komponentmodellen må gi strengt flere netto poeng i både hovedtesten og testen uten chips. Ingen justering av modeller, innstillinger eller ressursgrenser etter resultatene.','',
       f'{v["full_seasons"]} komplette sesonger; {len(v["technical_stops"])} tekniske stopp. Alle {v["decisions_replayed"]} lagrede rundevalg og poengoppgjør er kontrollert mot regler, budsjett, kaptein, benk, chips og byttekostnader. Ufullførte forsøk har ingen konstruert sesongtotal.','',
       '## Hva resultatet betyr','',
       ('Komponentmodellen består den nye historiske sammenligningen og robusthetskravet. Den er aktuell for praktisk innkobling og kontroll på ferske innganger.' if passed else 'Det forhåndsvalgte kravet for å gå videre til praktisk innkobling er ikke dokumentert. Dagens modell beholdes. Et manglende eller negativt resultat skal ikke skjules med et nytt oppsett eller en ny tilfeldig kjøring.'),'',
       '2025/26 er en ny sesong for denne konkrete managerpakken, men sesongen var tidligere undersøkt for prognosefeil og andre modeller. Dette er en tidsmessig utvidet historisk kontroll, ikke urørt bekreftelse. Testen bruker ett felles fryst regelsett, inkludert fem oppsparte gratisbytter. Historiske markedsdata, tidsstempler og registrert spillerutvalg har fortsatt dokumenterte proxyer.','',
       '## Kontroller før komponentmodellen kan bli hovedmodell','',
       '1. **Modellpakken må kunne kjøres på ferske data.** Samme komponentberegning, minuttprognoser og åtte separate fremtidige rundeanslag som i forsøket må inngå i den operative kjøringen. Modell, featureliste og oppdateringsrytme må være versjonert, og eksport/innlesing må gjenskape forskningsprognosene.',
       '2. **Én felles, fersk inngang ved faktisk tidspunkt.** Hele kjøpbare spillerutvalget, priser, posisjoner, klubber, full kvalifisert historikk, fravær, dødballroller, belastning og datert kampkalender må samles før fristen. Begge modeller skal få samme informasjon og den faktiske lagtilstanden. Faktisk fremtidig kampvær inngår ikke i denne komponentpakken.',
       '3. **Praktisk kontroll av ditt lag.** Begge modellene kjøres fra samme eierskap, kjøpspriser, bank, gratisbytter og tilgjengelige chips. Forskjeller i bytter, kaptein, benk og prognoser skal vises, og valgene kontrolleres for lovlighet og budsjett.',
       '4. **Lagring før utfallet.** Første nye prognoser og anbefalinger må få en tidsstemplet kvittering før runden starter. Deretter scores begge fortløpende på de samme utfallene. En etterberegnet prognose får aldri et tidligere tidsstempel.','',
       'Bestått historisk test åpner for denne driftskontrollen. Første kontroll på ferske innganger skal avdekke koblingsfeil; én fremtidig runde alene avgjør ikke langsiktig modellkvalitet. Dagens modell beholdes som sammenligningsgrunnlag også ved et senere bytte. Ingen FPL-overganger er utført og aktiv modell er ikke endret av dette forsøket.','',
       '## Hva som faktisk er testet','',
       '- Samme valgte komponentoppskrift og 325 tillatte grunnfelt som i hovedforsøket. Ti allerede låste, tidskontrollerte H1/H3-modellpakker for 2025/26 er gjenbrukt. Ingen ny arkitektur eller innstillingssøk.',
       '- Åtte uavhengige fremtidshoder med samme residualmetode som før, oppdatert ved GW1, 9, 17, 25 og 33. Bare tidligere prognoseopprinnelser med komplett og tilgjengelig fasit inngår. 40 hoder totalt; 32 ferdige hoder ble bevart byte for byte etter en teknisk eksportretting.',
       '- Referansen bruker den aktive faste sesongkalibreringen og dens opprinnelige treningsarkiv fra 2022/23–2024/25, med fire runders oppdateringsrytme. Underliggende lagrede baseprognoser er kontrollert mot kildehash, spillerutvalg og tidligere tilgjengelig statistikk. Den kjente historiske nullradsvakheten i den aktive referansen er bevart og dokumentert. Dette sammenligner operative pakker, ikke to nytrente arkitekturer med identisk treningsoppskrift.',
       '- Begge starter med tom tropp, £100 millioner og samme regler. Åtte runders prognoser, tre runders planlegging, inntil 40 løserkall og 16 noder per kall; én tråd. Ingen mislykket sesong er kjørt om igjen med mer ressurser.',
       '- 29 574 spiller–runde-rader fra daterte arkivutvalg. 409 manglende observasjonsrader er rekonstruert med tidligere informasjon. Ukjent fasit fylles ikke med null. Ved sesongslutt fylles bare ubrukte felt for runder etter GW38; ingen gyldig prognose er endret.','',
       f'[Poeng og byttekostnader]({P}/scores.csv) · [Etterkontroll av sesongene]({P}/manager_verification.json) · [Kontroll av prognoser og modelltilpasninger]({P}/forecast_verification.json) · [Låst testoppsett]({P}/proposal.json)','']
    if v['technical_stops']:
        lines+=['## Tekniske stopp','']
        for s in v['technical_stops']:lines.append(f'- {names[s["arm"]]}, {labels[s["setting"]]}: {s["completed_rounds"]} ferdige runder. {s["reason"]}')
    diag=pd.read_csv(P/'forecast_diagnostics.csv').pivot(index='arm',columns='horizon',values='mse');calendar=pd.read_csv(P/'calendar_diagnostics.csv');known=float(calendar.known_current_calendar.sum()/calendar.players.sum());diaglines=['## Kort vurdering av forskjellen','','Tre poeng i hovedtesten er en svært liten observert forskjell. Det er ikke dokumentasjon på at komponentmodellen generelt er dårligere, men det oppfyller heller ikke det forhåndslåste kravet om flere netto poeng i hovedoppsettet. Testen uten chips peker i positiv retning. Begge resultater skal beholdes.','','Komponentmodellen har lavere poeng-MSE enn referansen på de samme kjente fasitene etter åtterundersberegningen:','','| Horisont | Komponentmodell MSE | Dagens modell MSE | Lavere feil |','|---|---:|---:|---:|']
    for h in [1,3,8]:
        a=diag.loc['component',h];b=diag.loc['operational_fixed',h];diaglines.append(f'| {h} runder | {a:.4f} | {b:.4f} | {(1-a/b)*100:.2f} % |')
    diaglines+=['','Bedre prognosefeil ble dermed ikke en ny seier i managerens hovedoppsett. Chipstidspunkter, bytter, kaptein og lagutvikling ble forskjellige. Forskjellen mellom kjøring med og uten chips isolerer ikke effekten av én bestemt chip, siden resten av beslutningene også endres.','',f'Historisk kalender er en viktig praktisk begrensning: kvalifiserte kampantall i den felles H8-beregningen var kjent for {known*100:.1f} % av spiller–rundene, med minst noe dekning ved {int((calendar.known_share>0).sum())} av 38 tidspunkter. Resten beholdes som ukjent. Den aktive referansens arkiverte kalender hadde 10 ferske, 24 foreldede og 4 manglende tidspunkter. Dette er en kontroll under rekonstruerte kilder, og gir ikke direkte svaret på resultatet med ferske førfristdata.','', 'Før utskifting trenger vi derfor en sammenligning med fersk, datert kalender og komplette innganger, med prognoser lagret før utfall. Resepten bør holdes fast i den testen; resultatene fra 2025/26 skal ikke brukes til å velge nye chipstidspunkter i ettertid.','',f'[Chipstidspunkter og hele rundens netto poeng]({P}/chip_diagnostics.csv) · [Rundeoppgjør for begge oppsett]({P}/round_diagnostics.csv) · [Prognosefeil]({P}/forecast_diagnostics.csv) · [Kalenderdekning]({P}/calendar_diagnostics.csv)','']
    pos=lines.index('## Kontroller før komponentmodellen kan bli hovedmodell');lines[pos:pos]=diaglines
    report=P/'RESULTATER.md';report.write_text('\n'.join(lines));deps=[P/n for n in ['RESULTATER.md','scores.csv','manager_verification.json','forecast_verification.json','prediction_lock.json','projection_audit.csv','preflight.json','proposal.json','attempts.json','round_diagnostics.csv','chip_diagnostics.csv','forecast_diagnostics.csv','calendar_diagnostics.csv']]
    result=dict(conclusion='Komponentmodell mot aktiv modell på2025/26, samme manager og separat no-chip-stress: '+('forhåndslåst krav bestått; gå til fersk driftskontroll, ingen automatisk aktivering.' if passed else 'forhåndslåst krav ikke dokumentert; behold aktiv modell og forskningsresultater.'),decision='promote_to_review' if passed else 'retain_for_research',results=scores.astype(object).where(scores.notna(),None).to_dict('records'),paired_results=v['paired_results'],confirmation_gate_passed=passed,production_changed=False,evidence_hashes={str(p.relative_to(R)):sha(p) for p in deps});atomic_json(P/'result.json',result)
    overview=R/'overview/COMPONENT_ADOPTION_READINESS_2026_10_25.md';overview.write_text(report.read_text());atomic_json(R/'overview/COMPONENT_CANDIDATE.json',dict(candidate='common_component_h8_v1',status='historical_confirmation_passed_live_input_integration_pending' if passed else 'historical_confirmation_not_passed',historical_result=str((P/'result.json').relative_to(R)),overview=str(overview.relative_to(R)),operational_model_unchanged=True,next_gate='fresh input/runtime and actual team paired replay' if passed else 'diagnose failed gate without outcome-driven retuning'))
    root=R/'README.md';text=root.read_text();text=text.replace('# FPL prosjektoversikt\n','# FPL prosjektoversikt\n\n**Komponentmodell – ny kontroll:** [2025/26-test og hva som gjenstår før bruk](overview/COMPONENT_ADOPTION_READINESS_2026_10_25.md). Aktiv modell er bevart.\n',1);root.write_text(text)
    nextfile=R/'overview/NEXT.md';nextfile.write_text('# Komponentmodell – oppdatert vurdering\n\n[Ny sammenligning og konkrete gjenstående kontroller](COMPONENT_ADOPTION_READINESS_2026_10_25.md). Denne vurderingen supplerer den brede modelltesten nedenfor. Aktiv modell er ikke byttet.\n\n'+nextfile.read_text())
    evidence={str(f.relative_to(P)):sha(f) for f in sorted(P.rglob('*')) if f.is_file()};atomic_json(P/'evidence_manifest.json',dict(files=evidence));atomic_json(P/'completion.json',dict(passed=True,confirmation_gate_passed=passed,full_seasons=v['full_seasons'],decisions_verified=v['decisions_replayed'],overview_sha256=sha(overview),evidence_sha256=sha(P/'evidence_manifest.json'),production_changed=False));print('COMPONENT CONFIRMATION REPORTED',passed,flush=True)
if __name__=='__main__':main()
